PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, provider TEXT NOT NULL, provider_subject TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(provider, provider_subject));
CREATE TABLE user_settings (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, day_boundary_time TEXT NOT NULL DEFAULT '00:00' CHECK(length(day_boundary_time)=5), journal_prompt_time TEXT NOT NULL DEFAULT '21:00' CHECK(length(journal_prompt_time)=5), timezone TEXT NOT NULL, schema_version INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL);
CREATE TABLE plushes (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 60), icon_object_key TEXT, hidden INTEGER NOT NULL DEFAULT 0 CHECK(hidden IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX idx_plushes_user ON plushes(user_id, hidden, created_at);
CREATE TABLE posts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, body TEXT NOT NULL DEFAULT '' CHECK(length(body)<=300), time_mode TEXT NOT NULL CHECK(time_mode IN ('known','unknown')), occurred_local_datetime TEXT, manual_logical_date TEXT, latitude REAL CHECK(latitude BETWEEN -90 AND 90), longitude REAL CHECK(longitude BETWEEN -180 AND 180), place_name TEXT, place_source TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK((time_mode='known' AND occurred_local_datetime IS NOT NULL AND manual_logical_date IS NULL) OR (time_mode='unknown' AND occurred_local_datetime IS NULL AND manual_logical_date IS NOT NULL)), CHECK((latitude IS NULL AND longitude IS NULL) OR (latitude IS NOT NULL AND longitude IS NOT NULL)));
CREATE INDEX idx_posts_user_created ON posts(user_id, created_at);
CREATE INDEX idx_posts_user_manual_date ON posts(user_id, manual_logical_date);
CREATE TABLE post_plushes (post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, plush_id TEXT NOT NULL REFERENCES plushes(id) ON DELETE RESTRICT, display_order INTEGER NOT NULL CHECK(display_order>=0), PRIMARY KEY(post_id,plush_id));
CREATE TABLE post_images (id TEXT PRIMARY KEY, post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, full_object_key TEXT NOT NULL UNIQUE, thumbnail_object_key TEXT NOT NULL UNIQUE, display_order INTEGER NOT NULL CHECK(display_order BETWEEN 0 AND 3), is_cover INTEGER NOT NULL DEFAULT 0 CHECK(is_cover IN (0,1)), width INTEGER NOT NULL CHECK(width>0), height INTEGER NOT NULL CHECK(height>0), mime_type TEXT NOT NULL, byte_size INTEGER NOT NULL CHECK(byte_size>0), created_at TEXT NOT NULL, UNIQUE(post_id,display_order));
CREATE TABLE daily_journals (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, logical_date TEXT NOT NULL, body TEXT NOT NULL DEFAULT '' CHECK(length(body)<=1000), last_post_change_at_at_save TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(user_id,logical_date));
